messages.content:
Tool response:
Tool: place_limit_order
Description: Place a limit order to buy securities
Parameters:
    {
      "type": "object",
      "properties": {
        "account_id": {
          "type": "integer",
          "title": "Account Id",
          "description": "Internal ID of the account to place the order from"
        },
        "security_symbol": {
          "type": "string",
          "title": "Security Symbol",
          "description": "Stock symbol of the security to trade (e.g., AAPL)"
        },
        "quantity": {
          "type": "integer",
          "exclusiveMinimum": 0.0,
          "title": "Quantity",
          "description": "Number of shares to buy"
        },
        "limit_price": {
          "type": "number",
          "exclusiveMinimum": 0.0,
          "title": "Limit Price",
          "description": "Maximum price to pay per share"
        },
        "time_in_force": {
          "type": "string",
          "title": "Time In Force",
          "description": "Order duration: Day, GTC, IOC, FOK, GTD"
        },
        "trading_platform": {
          "type": "string",
          "title": "Trading Platform",
          "description": "Platform used to place the order: thinkorswim, schwab, web, mobile"
        }
      },
      "required": [
        "account_id",
        "security_symbol",
        "quantity",
        "limit_price",
        "time_in_force",
        "trading_platform"
      ]
    }
